export const WP_THEME_STYLE_CSS = "/*\nTheme Name: Atelier Editorial\nTheme URI: https://atelier-editorial.local\nAuthor: Waleed Alharbi\nAuthor URI: https://waleedalharbi.com\nDescription: A refined editorial monograph theme for WordPress. Features Newsreader serifs, distraction-free reading views, drop caps, reading time indicators, 65-character optical measures, 7:5 lead story layouts, and clean author-driven publishing with no keywords, hashtags, or category clutter.\nVersion: 1.2.0\nRequires at least: 5.9\nTested up to: 6.7\nRequires PHP: 7.4\nLicense: GNU General Public License v2 or later\nLicense URI: http://www.gnu.org/licenses/gpl-2.0.html\nText Domain: atelier-editorial\n*/\n\n/* 1. Google Fonts Direct Font Face Import */\n@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;600&family=Newsreader:ital,opsz,wght@0,6..72,400;0,6..72,500;0,6..72,600;1,6..72,400;1,6..72,500&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap');\n\n/* ==========================================================================\n   2. DESIGN TOKENS & SYSTEM VARIABLES\n   ========================================================================== */\n:root {\n  --bg-canvas: #FAF8F5;\n  --bg-card: #FFFFFF;\n  --bg-subtle: #F2EDE4;\n  --bg-surface: #F5F5F4;\n  --text-primary: #1C1917;\n  --text-secondary: #57534E;\n  --text-muted: #78716C;\n  --text-subtle: #A8A29E;\n  --border-subtle: #E7E5E4;\n  --border-strong: #D6D3D1;\n  --border-dark: #1C1917;\n  --accent-emerald: #065F46;\n  --accent-emerald-bg: #ECFDF5;\n  --font-serif: 'Newsreader', Georgia, 'Times New Roman', serif;\n  --font-sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\n  --font-mono: 'JetBrains Mono', SFMono-Regular, Menlo, Monaco, Consolas, monospace;\n  --site-width: 1152px;\n  --reader-measure: 720px;\n  --transition-smooth: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);\n}\n\n/* ==========================================================================\n   3. BASE RESET & ACCESSIBILITY\n   ========================================================================== */\n*, *::before, *::after {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nhtml {\n  font-size: 16px;\n  scroll-behavior: smooth;\n  -webkit-text-size-adjust: 100%;\n}\n\nbody {\n  background-color: var(--bg-canvas);\n  color: var(--text-primary);\n  font-family: var(--font-sans);\n  line-height: 1.65;\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n  min-height: 100vh;\n  display: flex;\n  flex-direction: column;\n}\n\na {\n  color: inherit;\n  text-decoration: none;\n  transition: var(--transition-smooth);\n}\n\nimg {\n  max-width: 100%;\n  height: auto;\n  display: block;\n}\n\n.site-container {\n  max-width: var(--site-width);\n  margin: 0 auto;\n  padding: 0 1.5rem;\n  width: 100%;\n}\n\n.site-main {\n  flex: 1 0 auto;\n  padding: 2.5rem 0 5rem;\n}\n\n/* Screen reader text */\n.screen-reader-text {\n  border: 0;\n  clip: rect(1px, 1px, 1px, 1px);\n  clip-path: inset(50%);\n  height: 1px;\n  margin: -1px;\n  overflow: hidden;\n  padding: 0;\n  position: absolute !important;\n  width: 1px;\n  word-wrap: normal !important;\n}\n\n.screen-reader-text:focus {\n  background-color: #1C1917;\n  border-radius: 4px;\n  color: #FFFFFF;\n  clip: auto !important;\n  clip-path: none;\n  display: block;\n  font-size: 0.875rem;\n  height: auto;\n  left: 1rem;\n  top: 1rem;\n  padding: 0.75rem 1.25rem;\n  text-decoration: none;\n  width: auto;\n  z-index: 100000;\n}\n\n/* ==========================================================================\n   4. TOP MASTHEAD TICKER\n   ========================================================================== */\n.top-masthead-ticker {\n  background-color: #F5F2EB;\n  border-bottom: 1px solid var(--border-subtle);\n  font-family: var(--font-mono);\n  font-size: 0.6875rem;\n  color: var(--text-muted);\n  padding: 0.45rem 0;\n}\n\n.ticker-inner {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.ticker-left {\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n}\n\n.ticker-dot {\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  background-color: var(--accent-emerald);\n  display: inline-block;\n}\n\n.ticker-divider {\n  color: var(--border-strong);\n}\n\n.ticker-freq {\n  color: var(--text-subtle);\n}\n\n.ticker-right {\n  display: none;\n  align-items: center;\n  gap: 0.5rem;\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n}\n\n@media (min-width: 680px) {\n  .ticker-right {\n    display: flex;\n  }\n}\n\n/* ==========================================================================\n   5. SITE HEADER & NAVIGATION\n   ========================================================================== */\n.site-header {\n  background-color: rgba(250, 248, 245, 0.94);\n  backdrop-filter: blur(12px);\n  -webkit-backdrop-filter: blur(12px);\n  border-bottom: 1px solid var(--border-subtle);\n  position: sticky;\n  top: 0;\n  z-index: 50;\n}\n\n/* Respect WordPress Admin Bar */\nbody.admin-bar .site-header {\n  top: 32px;\n}\n@media screen and (max-width: 782px) {\n  body.admin-bar .site-header {\n    top: 46px;\n  }\n}\n\n.header-inner {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 1.1rem 0;\n}\n\n.header-brand-group {\n  display: flex;\n  align-items: center;\n  gap: 0.85rem;\n}\n\n.brand-link {\n  display: flex;\n  flex-direction: column;\n}\n\n.brand-title {\n  font-family: var(--font-serif);\n  font-size: 1.6rem;\n  font-weight: 500;\n  letter-spacing: -0.02em;\n  color: var(--text-primary);\n  line-height: 1.1;\n}\n\n.brand-subtitle {\n  font-family: var(--font-mono);\n  font-size: 0.625rem;\n  text-transform: uppercase;\n  letter-spacing: 0.16em;\n  color: var(--text-subtle);\n  margin-top: 0.15rem;\n}\n\n.brand-author-pill {\n  font-family: var(--font-mono);\n  font-size: 0.65rem;\n  text-transform: uppercase;\n  letter-spacing: 0.12em;\n  color: var(--text-secondary);\n  border: 1px solid var(--border-subtle);\n  background-color: #FFFFFF;\n  padding: 0.2rem 0.6rem;\n  border-radius: 4px;\n}\n\n.site-navigation .nav-menu {\n  display: flex;\n  list-style: none;\n  gap: 1.75rem;\n  align-items: center;\n}\n\n.site-navigation .nav-menu a {\n  font-size: 0.8125rem;\n  font-weight: 500;\n  color: var(--text-secondary);\n  position: relative;\n  padding: 0.25rem 0;\n}\n\n.site-navigation .nav-menu a:hover,\n.site-navigation .nav-menu .current-menu-item a {\n  color: var(--text-primary);\n}\n\n.site-navigation .nav-menu .current-menu-item a::after {\n  content: '';\n  position: absolute;\n  bottom: 0;\n  left: 0;\n  right: 0;\n  height: 1.5px;\n  background-color: var(--text-primary);\n}\n\n.header-actions {\n  display: flex;\n  align-items: center;\n  gap: 0.625rem;\n}\n\n.btn-search-toggle,\n.btn-rss {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.4rem;\n  font-family: var(--font-sans);\n  font-size: 0.75rem;\n  font-weight: 500;\n  color: var(--text-secondary);\n  background-color: #FFFFFF;\n  border: 1px solid var(--border-subtle);\n  border-radius: 6px;\n  padding: 0.4rem 0.75rem;\n  cursor: pointer;\n  transition: var(--transition-smooth);\n}\n\n.btn-search-toggle:hover,\n.btn-rss:hover {\n  background-color: var(--bg-subtle);\n  color: var(--text-primary);\n  border-color: var(--border-strong);\n}\n\n.header-search-drawer {\n  display: none;\n  padding: 0.75rem 0 1.25rem;\n  border-top: 1px solid var(--border-subtle);\n}\n\n.header-search-drawer.is-open {\n  display: block;\n}\n\n/* ==========================================================================\n   6. ASYMMETRIC LEAD STORY (HERO MONOGRAPH)\n   ========================================================================== */\n.hero-lead-section {\n  padding: 1.5rem 0 3.5rem;\n  border-bottom: 1px solid var(--border-subtle);\n  margin-bottom: 3.5rem;\n}\n\n.hero-lead-grid {\n  display: grid;\n  grid-template-columns: 1fr;\n  gap: 2.5rem;\n  align-items: center;\n}\n\n@media (min-width: 900px) {\n  .hero-lead-grid {\n    grid-template-columns: 1.15fr 0.95fr;\n    gap: 3.5rem;\n  }\n}\n\n.hero-lead-kicker {\n  display: flex;\n  align-items: center;\n  gap: 0.75rem;\n  margin-bottom: 1rem;\n}\n\n.kicker-pill {\n  font-family: var(--font-mono);\n  font-size: 0.6875rem;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.12em;\n  color: var(--accent-emerald);\n  background-color: var(--accent-emerald-bg);\n  border: 1px solid rgba(6, 95, 70, 0.2);\n  padding: 0.2rem 0.55rem;\n  border-radius: 4px;\n}\n\n.kicker-date {\n  font-family: var(--font-mono);\n  font-size: 0.75rem;\n  color: var(--text-muted);\n}\n\n.hero-lead-title {\n  font-family: var(--font-serif);\n  font-size: clamp(2.15rem, 3.8vw, 2.85rem);\n  font-weight: 400;\n  line-height: 1.18;\n  letter-spacing: -0.025em;\n  color: var(--text-primary);\n  margin-bottom: 1.25rem;\n}\n\n.hero-lead-title a:hover {\n  color: var(--text-secondary);\n}\n\n.hero-lead-excerpt {\n  font-size: 1.0625rem;\n  line-height: 1.7;\n  color: var(--text-secondary);\n  margin-bottom: 1.75rem;\n}\n\n.hero-lead-footer {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  flex-wrap: wrap;\n  gap: 1rem;\n  padding-top: 1.25rem;\n  border-top: 1px solid var(--border-subtle);\n}\n\n.hero-author-badge {\n  display: flex;\n  align-items: center;\n  gap: 0.65rem;\n}\n\n.author-avatar-mini {\n  width: 32px;\n  height: 32px;\n  border-radius: 50%;\n  background-color: #1C1917;\n  color: #FFFFFF;\n  font-family: var(--font-serif);\n  font-size: 0.95rem;\n  font-weight: bold;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.author-meta-text {\n  display: flex;\n  flex-direction: column;\n}\n\n.author-meta-text .author-name {\n  font-size: 0.8125rem;\n  font-weight: 600;\n  color: var(--text-primary);\n}\n\n.author-meta-text .author-role {\n  font-family: var(--font-mono);\n  font-size: 0.6875rem;\n  color: var(--text-muted);\n}\n\n.hero-cta-button {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.5rem;\n  background-color: #1C1917;\n  color: #FFFFFF;\n  font-size: 0.8125rem;\n  font-weight: 500;\n  padding: 0.55rem 1rem;\n  border-radius: 6px;\n  transition: var(--transition-smooth);\n}\n\n.hero-cta-button:hover {\n  background-color: #383532;\n  transform: translateY(-1px);\n}\n\n.hero-lead-media {\n  position: relative;\n  overflow: hidden;\n  border-radius: 12px;\n  border: 1px solid var(--border-subtle);\n  background-color: #E7E5E4;\n}\n\n.hero-media-anchor {\n  display: block;\n}\n\n.hero-media-img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  aspect-ratio: 16 / 10;\n  transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);\n}\n\n.hero-lead-media:hover .hero-media-img {\n  transform: scale(1.025);\n}\n\n/* ==========================================================================\n   7. MONOGRAPH EDITORIAL GRID (BALANCED AUTO-FILL)\n   ========================================================================== */\n.ledger-section-header {\n  display: flex;\n  align-items: flex-end;\n  justify-content: space-between;\n  margin-bottom: 2rem;\n  padding-bottom: 1rem;\n  border-bottom: 1px solid var(--border-subtle);\n}\n\n.ledger-section-title {\n  font-family: var(--font-serif);\n  font-size: 1.75rem;\n  font-weight: 400;\n  color: var(--text-primary);\n  line-height: 1.2;\n}\n\n.ledger-section-desc {\n  font-size: 0.875rem;\n  color: var(--text-muted);\n  margin-top: 0.25rem;\n}\n\n.ledger-count-indicator {\n  font-family: var(--font-mono);\n  font-size: 0.6875rem;\n  text-transform: uppercase;\n  letter-spacing: 0.1em;\n  color: var(--text-muted);\n  background-color: var(--bg-subtle);\n  padding: 0.25rem 0.6rem;\n  border-radius: 4px;\n}\n\n.monographs-editorial-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));\n  gap: 2.25rem;\n}\n\n.monograph-card {\n  background-color: #FFFFFF;\n  border: 1px solid var(--border-subtle);\n  border-radius: 10px;\n  overflow: hidden;\n  display: flex;\n  flex-direction: column;\n  transition: var(--transition-smooth);\n}\n\n.monograph-card:hover {\n  border-color: var(--border-strong);\n  box-shadow: 0 8px 24px -10px rgba(0, 0, 0, 0.08);\n  transform: translateY(-2px);\n}\n\n.card-media-wrapper {\n  position: relative;\n  overflow: hidden;\n  aspect-ratio: 16 / 10;\n  background-color: #F2EDE4;\n}\n\n.card-thumbnail-img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  transition: transform 0.5s ease-out;\n}\n\n.monograph-card:hover .card-thumbnail-img {\n  transform: scale(1.035);\n}\n\n.card-content-wrapper {\n  padding: 1.35rem;\n  display: flex;\n  flex-direction: column;\n  flex: 1 0 auto;\n}\n\n.card-unboxed-meta {\n  font-family: var(--font-mono);\n  font-size: 0.6875rem;\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n  color: var(--text-muted);\n  margin-bottom: 0.65rem;\n}\n\n.card-monograph-title {\n  font-family: var(--font-serif);\n  font-size: 1.35rem;\n  font-weight: 400;\n  line-height: 1.3;\n  color: var(--text-primary);\n  margin-bottom: 0.75rem;\n}\n\n.card-monograph-title a:hover {\n  color: var(--text-secondary);\n}\n\n.card-monograph-excerpt {\n  font-size: 0.875rem;\n  line-height: 1.6;\n  color: var(--text-secondary);\n  margin-bottom: 1.25rem;\n  flex-grow: 1;\n}\n\n.card-monograph-footer {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding-top: 0.85rem;\n  border-top: 1px solid var(--border-subtle);\n  font-size: 0.75rem;\n}\n\n.card-curator {\n  font-family: var(--font-mono);\n  font-size: 0.6875rem;\n  color: var(--text-subtle);\n}\n\n.card-read-link {\n  font-weight: 600;\n  color: var(--text-primary);\n}\n\n.card-read-link:hover {\n  color: var(--accent-emerald);\n}\n\n/* ==========================================================================\n   8. CURATORIAL QUOTE BREAK, METRICS & PILLARS\n   ========================================================================== */\n.curatorial-quote-break {\n  margin: 4.5rem 0 3.5rem;\n  padding: 3.25rem 1.5rem;\n  border-top: 1px solid var(--border-subtle);\n  border-bottom: 1px solid var(--border-subtle);\n  background-color: #F8F5EF;\n  border-radius: 12px;\n  text-align: center;\n}\n\n.quote-break-inner {\n  max-width: 680px;\n  margin: 0 auto;\n}\n\n.quote-ornament {\n  font-family: var(--font-serif);\n  font-size: 3rem;\n  line-height: 1;\n  color: var(--text-subtle);\n  display: block;\n  margin-bottom: -1rem;\n}\n\n.quote-break-text {\n  font-family: var(--font-serif);\n  font-style: italic;\n  font-size: clamp(1.25rem, 2.5vw, 1.625rem);\n  line-height: 1.45;\n  color: var(--text-primary);\n  margin-bottom: 1rem;\n}\n\n.quote-break-author {\n  font-family: var(--font-mono);\n  font-size: 0.75rem;\n  text-transform: uppercase;\n  letter-spacing: 0.1em;\n  color: var(--text-muted);\n}\n\n/* Archival Metrics Section */\n.archival-metrics-section {\n  margin-bottom: 4rem;\n}\n\n.metrics-grid {\n  display: grid;\n  grid-template-columns: repeat(2, 1fr);\n  gap: 1.25rem;\n}\n\n@media (min-width: 860px) {\n  .metrics-grid {\n    grid-template-columns: repeat(4, 1fr);\n  }\n}\n\n.metric-card {\n  background-color: #FFFFFF;\n  border: 1px solid var(--border-subtle);\n  border-radius: 10px;\n  padding: 1.5rem;\n  display: flex;\n  flex-direction: column;\n}\n\n.metric-num {\n  font-family: var(--font-serif);\n  font-size: 2rem;\n  font-weight: 500;\n  color: var(--text-primary);\n  margin-bottom: 0.25rem;\n}\n\n.metric-label {\n  font-size: 0.8125rem;\n  font-weight: 600;\n  color: var(--text-primary);\n  margin-bottom: 0.25rem;\n}\n\n.metric-sub {\n  font-size: 0.75rem;\n  color: var(--text-muted);\n  line-height: 1.4;\n}\n\n/* Editorial Pillars Section */\n.editorial-pillars-section {\n  margin-bottom: 4.5rem;\n  padding-top: 1rem;\n}\n\n.pillars-header {\n  margin-bottom: 2.25rem;\n  text-align: center;\n  max-width: 640px;\n  margin-left: auto;\n  margin-right: auto;\n}\n\n.pillars-kicker {\n  font-family: var(--font-mono);\n  font-size: 0.6875rem;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.14em;\n  color: var(--text-muted);\n  display: block;\n  margin-bottom: 0.5rem;\n}\n\n.pillars-title {\n  font-family: var(--font-serif);\n  font-size: 2rem;\n  font-weight: 400;\n  color: var(--text-primary);\n  margin-bottom: 0.75rem;\n}\n\n.pillars-desc {\n  font-size: 0.9375rem;\n  color: var(--text-secondary);\n  line-height: 1.6;\n}\n\n.pillars-grid {\n  display: grid;\n  grid-template-columns: 1fr;\n  gap: 1.5rem;\n}\n\n@media (min-width: 640px) {\n  .pillars-grid {\n    grid-template-columns: repeat(2, 1fr);\n  }\n}\n\n@media (min-width: 960px) {\n  .pillars-grid {\n    grid-template-columns: repeat(4, 1fr);\n  }\n}\n\n.pillar-box {\n  background-color: #FFFFFF;\n  border: 1px solid var(--border-subtle);\n  border-radius: 10px;\n  padding: 1.75rem;\n  display: flex;\n  flex-direction: column;\n}\n\n.pillar-number {\n  font-family: var(--font-mono);\n  font-size: 0.75rem;\n  color: var(--text-subtle);\n  margin-bottom: 0.85rem;\n}\n\n.pillar-box-title {\n  font-family: var(--font-serif);\n  font-size: 1.25rem;\n  font-weight: 400;\n  color: var(--text-primary);\n  margin-bottom: 0.6rem;\n}\n\n.pillar-box-body {\n  font-size: 0.8125rem;\n  line-height: 1.65;\n  color: var(--text-secondary);\n}\n\n/* Postal Dispatch */\n.postal-dispatch-section {\n  margin-bottom: 4rem;\n}\n\n.postal-box-container {\n  background-color: #FFFFFF;\n  border: 1px solid var(--border-subtle);\n  border-radius: 12px;\n  padding: 2.5rem;\n  display: grid;\n  grid-template-columns: 1fr;\n  gap: 2rem;\n  align-items: center;\n}\n\n@media (min-width: 860px) {\n  .postal-box-container {\n    grid-template-columns: 1.2fr 1fr;\n  }\n}\n\n.postal-kicker {\n  font-family: var(--font-mono);\n  font-size: 0.6875rem;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.14em;\n  color: var(--text-muted);\n  display: block;\n  margin-bottom: 0.5rem;\n}\n\n.postal-heading {\n  font-family: var(--font-serif);\n  font-size: 1.5rem;\n  font-weight: 400;\n  color: var(--text-primary);\n  margin-bottom: 0.5rem;\n}\n\n.postal-sub {\n  font-size: 0.875rem;\n  color: var(--text-secondary);\n}\n\n.postal-subscribe-form {\n  display: flex;\n  gap: 0.5rem;\n}\n\n.postal-email-input {\n  flex: 1;\n  padding: 0.65rem 0.9rem;\n  font-family: var(--font-sans);\n  font-size: 0.875rem;\n  border: 1px solid var(--border-strong);\n  border-radius: 6px;\n  background-color: var(--bg-canvas);\n  color: var(--text-primary);\n}\n\n.postal-email-input:focus {\n  outline: none;\n  border-color: #1C1917;\n  background-color: #FFFFFF;\n}\n\n.postal-submit-btn {\n  padding: 0.65rem 1.15rem;\n  background-color: #1C1917;\n  color: #FFFFFF;\n  border: none;\n  border-radius: 6px;\n  font-size: 0.8125rem;\n  font-weight: 500;\n  cursor: pointer;\n  white-space: nowrap;\n}\n\n.postal-submit-btn:hover {\n  background-color: #383532;\n}\n\n.postal-guarantee {\n  font-family: var(--font-mono);\n  font-size: 0.65rem;\n  color: var(--text-subtle);\n  display: block;\n  margin-top: 0.6rem;\n}\n\n/* ==========================================================================\n   9. SINGLE MONOGRAPH READER (OPTICAL MEASURE & DROP CAP)\n   ========================================================================== */\n.reader-monograph-article {\n  max-width: var(--reader-measure);\n  margin: 0 auto;\n}\n\n.reader-top-bar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  font-family: var(--font-mono);\n  font-size: 0.75rem;\n  color: var(--text-muted);\n  padding-bottom: 1.25rem;\n  margin-bottom: 2rem;\n  border-bottom: 1px solid var(--border-subtle);\n}\n\n.reader-back-link {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.4rem;\n  color: var(--text-primary);\n  font-weight: 500;\n}\n\n.reader-back-link:hover {\n  color: var(--text-muted);\n}\n\n.reader-folio-indicator {\n  display: flex;\n  align-items: center;\n  gap: 0.4rem;\n}\n\n.folio-dot {\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  background-color: var(--accent-emerald);\n}\n\n.reader-monograph-header {\n  margin-bottom: 2.5rem;\n}\n\n.reader-unboxed-meta {\n  font-family: var(--font-mono);\n  font-size: 0.75rem;\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n  color: var(--text-muted);\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 0.5rem;\n  margin-bottom: 1.25rem;\n}\n\n.reader-monograph-title {\n  font-family: var(--font-serif);\n  font-size: clamp(2.25rem, 4.2vw, 3.25rem);\n  font-weight: 400;\n  line-height: 1.15;\n  letter-spacing: -0.02em;\n  color: var(--text-primary);\n  margin-bottom: 1rem;\n}\n\n.reader-monograph-subtitle {\n  font-family: var(--font-serif);\n  font-style: italic;\n  font-size: 1.25rem;\n  line-height: 1.5;\n  color: var(--text-secondary);\n  margin-bottom: 1.5rem;\n}\n\n.reader-byline-strip {\n  display: flex;\n  align-items: center;\n  gap: 0.75rem;\n  padding-top: 1.25rem;\n  border-top: 1px solid var(--border-subtle);\n}\n\n.byline-avatar {\n  width: 38px;\n  height: 38px;\n  border-radius: 50%;\n  background-color: #1C1917;\n  color: #FFFFFF;\n  font-family: var(--font-serif);\n  font-size: 1.1rem;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.byline-details {\n  display: flex;\n  flex-direction: column;\n}\n\n.byline-name {\n  font-size: 0.875rem;\n  font-weight: 600;\n}\n\n.byline-desc {\n  font-family: var(--font-mono);\n  font-size: 0.6875rem;\n  color: var(--text-muted);\n}\n\n.reader-featured-figure {\n  margin: 2rem 0 3rem;\n  border-radius: 12px;\n  overflow: hidden;\n  border: 1px solid var(--border-subtle);\n}\n\n.reader-featured-caption {\n  font-family: var(--font-mono);\n  font-size: 0.6875rem;\n  color: var(--text-muted);\n  text-align: center;\n  padding: 0.6rem 0.5rem;\n  background-color: #FFFFFF;\n  border-top: 1px solid var(--border-subtle);\n}\n\n/* Classical Editorial Drop-Cap */\n.editorial-drop-cap p:first-of-type::first-letter {\n  font-family: var(--font-serif);\n  font-size: 3.75rem;\n  line-height: 0.85;\n  float: left;\n  margin-right: 0.75rem;\n  margin-top: 0.25rem;\n  font-weight: 500;\n  color: var(--text-primary);\n}\n\n.reader-prose-container {\n  font-size: 1.0625rem;\n  line-height: 1.85;\n  color: #383532;\n}\n\n.reader-prose-container p {\n  margin-bottom: 1.85rem;\n}\n\n.reader-prose-container h2 {\n  font-family: var(--font-serif);\n  font-size: 1.85rem;\n  font-weight: 400;\n  margin: 3rem 0 1.25rem;\n  line-height: 1.25;\n  color: var(--text-primary);\n}\n\n.reader-prose-container h3 {\n  font-family: var(--font-serif);\n  font-size: 1.45rem;\n  font-weight: 400;\n  margin: 2.25rem 0 1rem;\n  color: var(--text-primary);\n}\n\n.reader-prose-container blockquote {\n  font-family: var(--font-serif);\n  font-style: italic;\n  font-size: 1.55rem;\n  line-height: 1.35;\n  color: var(--text-primary);\n  border-top: 1px solid var(--border-strong);\n  border-bottom: 1px solid var(--border-strong);\n  padding: 1.75rem 1rem;\n  margin: 2.75rem 0;\n  text-align: center;\n}\n\n.reader-prose-container blockquote cite {\n  font-family: var(--font-mono);\n  font-style: normal;\n  font-size: 0.75rem;\n  text-transform: uppercase;\n  letter-spacing: 0.1em;\n  color: var(--text-muted);\n  display: block;\n  margin-top: 0.75rem;\n}\n\n/* Author Attribution Card */\n.reader-author-card {\n  margin: 4.5rem 0 3rem;\n  padding: 2rem;\n  background-color: #FFFFFF;\n  border: 1px solid var(--border-subtle);\n  border-radius: 12px;\n}\n\n.author-card-inner {\n  display: flex;\n  gap: 1.5rem;\n  align-items: flex-start;\n}\n\n.author-portrait-placeholder {\n  width: 54px;\n  height: 54px;\n  border-radius: 50%;\n  background-color: #1C1917;\n  color: #FFFFFF;\n  font-family: var(--font-serif);\n  font-size: 1.5rem;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  shrink: 0;\n}\n\n.author-card-role {\n  font-family: var(--font-mono);\n  font-size: 0.65rem;\n  font-weight: 600;\n  letter-spacing: 0.12em;\n  color: var(--text-muted);\n  display: block;\n  margin-bottom: 0.25rem;\n}\n\n.author-card-name {\n  font-family: var(--font-serif);\n  font-size: 1.35rem;\n  font-weight: 400;\n  margin-bottom: 0.5rem;\n}\n\n.author-card-bio {\n  font-size: 0.875rem;\n  line-height: 1.65;\n  color: var(--text-secondary);\n  margin-bottom: 1rem;\n}\n\n.author-card-actions {\n  display: flex;\n  gap: 1.25rem;\n  font-size: 0.8125rem;\n  font-weight: 500;\n}\n\n.author-card-link {\n  color: var(--text-primary);\n}\n\n.author-card-link:hover {\n  color: var(--accent-emerald);\n}\n\n/* Adjacent Navigation */\n.reader-post-navigation {\n  margin: 3rem 0;\n  padding-top: 2rem;\n  border-top: 1px solid var(--border-subtle);\n}\n\n.nav-adjacent-grid {\n  display: grid;\n  grid-template-columns: 1fr;\n  gap: 1.5rem;\n}\n\n@media (min-width: 600px) {\n  .nav-adjacent-grid {\n    grid-template-columns: 1fr 1fr;\n  }\n}\n\n.nav-adjacent-cell {\n  background-color: #FFFFFF;\n  border: 1px solid var(--border-subtle);\n  border-radius: 8px;\n  padding: 1.25rem;\n  display: flex;\n  flex-direction: column;\n}\n\n.nav-cell-label {\n  font-family: var(--font-mono);\n  font-size: 0.6875rem;\n  text-transform: uppercase;\n  color: var(--text-muted);\n  margin-bottom: 0.4rem;\n}\n\n.nav-cell-title {\n  font-family: var(--font-serif);\n  font-size: 1.15rem;\n  line-height: 1.3;\n  color: var(--text-primary);\n}\n\n/* ==========================================================================\n   10. ARCHIVE, SEARCH & 404 LAYOUTS\n   ========================================================================== */\n.archive-ledger-header {\n  text-align: center;\n  max-width: 720px;\n  margin: 1.5rem auto 3.5rem;\n  padding-bottom: 2rem;\n  border-bottom: 1px solid var(--border-subtle);\n}\n\n.archive-kicker {\n  font-family: var(--font-mono);\n  font-size: 0.75rem;\n  letter-spacing: 0.16em;\n  text-transform: uppercase;\n  color: var(--text-muted);\n  margin-bottom: 0.75rem;\n}\n\n.archive-title {\n  font-family: var(--font-serif);\n  font-size: clamp(2rem, 3.5vw, 2.75rem);\n  font-weight: 400;\n  color: var(--text-primary);\n  margin-bottom: 0.75rem;\n}\n\n.archive-desc {\n  font-size: 1rem;\n  color: var(--text-secondary);\n}\n\n.search-page-form-wrap {\n  margin-top: 1.5rem;\n}\n\n.search-page-form-wrap form {\n  display: flex;\n  max-width: 480px;\n  margin: 0 auto;\n  gap: 0.5rem;\n}\n\n.search-page-form-wrap input[type=\"search\"] {\n  flex: 1;\n  padding: 0.6rem 0.9rem;\n  border: 1px solid var(--border-strong);\n  border-radius: 6px;\n  font-family: var(--font-sans);\n}\n\n.search-page-form-wrap button,\n.search-page-form-wrap input[type=\"submit\"] {\n  padding: 0.6rem 1.1rem;\n  background-color: #1C1917;\n  color: #FFFFFF;\n  border: none;\n  border-radius: 6px;\n  cursor: pointer;\n}\n\n/* 404 Error */\n.error-404-container {\n  padding: 5rem 0;\n  text-align: center;\n}\n\n.error-404-inner {\n  max-width: 580px;\n  margin: 0 auto;\n}\n\n.error-kicker {\n  font-family: var(--font-mono);\n  font-size: 0.75rem;\n  letter-spacing: 0.16em;\n  color: var(--text-muted);\n  display: block;\n  margin-bottom: 0.75rem;\n}\n\n.error-title {\n  font-family: var(--font-serif);\n  font-size: 2.5rem;\n  font-weight: 400;\n  margin-bottom: 1rem;\n}\n\n.error-desc {\n  font-size: 1rem;\n  color: var(--text-secondary);\n  margin-bottom: 2rem;\n}\n\n.error-search-box {\n  margin-bottom: 2rem;\n}\n\n.btn-return-home {\n  display: inline-block;\n  padding: 0.65rem 1.25rem;\n  background-color: #1C1917;\n  color: #FFFFFF;\n  border-radius: 6px;\n  font-size: 0.875rem;\n}\n\n/* Standalone Page */\n.editorial-page-wrapper {\n  max-width: var(--reader-measure);\n  margin: 0 auto;\n}\n\n.editorial-page-header {\n  margin-bottom: 2.5rem;\n  padding-bottom: 1.5rem;\n  border-bottom: 1px solid var(--border-subtle);\n}\n\n.editorial-page-kicker {\n  font-family: var(--font-mono);\n  font-size: 0.6875rem;\n  letter-spacing: 0.14em;\n  text-transform: uppercase;\n  color: var(--text-muted);\n  display: block;\n  margin-bottom: 0.75rem;\n}\n\n.editorial-page-title {\n  font-family: var(--font-serif);\n  font-size: 2.75rem;\n  font-weight: 400;\n  color: var(--text-primary);\n}\n\n.editorial-page-subtitle {\n  font-family: var(--font-serif);\n  font-style: italic;\n  font-size: 1.2rem;\n  color: var(--text-secondary);\n  margin-top: 0.5rem;\n}\n\n.editorial-page-content {\n  font-size: 1.0625rem;\n  line-height: 1.8;\n  color: #383532;\n}\n\n.editorial-page-content p {\n  margin-bottom: 1.75rem;\n}\n\n/* ==========================================================================\n   11. NUMERICAL PAGINATION\n   ========================================================================== */\n.pagination {\n  margin: 3.5rem 0 1rem;\n  display: flex;\n  justify-content: center;\n}\n\n.nav-links {\n  display: flex;\n  align-items: center;\n  gap: 0.35rem;\n  font-family: var(--font-mono);\n  font-size: 0.75rem;\n}\n\n.nav-links a,\n.nav-links span {\n  padding: 0.5rem 0.85rem;\n  border: 1px solid var(--border-subtle);\n  border-radius: 6px;\n  background-color: #FFFFFF;\n  color: var(--text-secondary);\n}\n\n.nav-links a:hover {\n  background-color: var(--bg-subtle);\n  color: var(--text-primary);\n  border-color: var(--border-strong);\n}\n\n.nav-links .current {\n  background-color: #1C1917;\n  color: #FFFFFF;\n  border-color: #1C1917;\n  font-weight: bold;\n}\n\n/* ==========================================================================\n   12. SITE FOOTER\n   ========================================================================== */\n.site-footer {\n  background-color: #FAF8F5;\n  border-top: 1px solid var(--border-subtle);\n  padding: 4rem 0 2.5rem;\n  margin-top: auto;\n}\n\n.footer-columns-grid {\n  display: grid;\n  grid-template-columns: 1fr;\n  gap: 3rem;\n  padding-bottom: 3.5rem;\n  border-bottom: 1px solid var(--border-subtle);\n}\n\n@media (min-width: 768px) {\n  .footer-columns-grid {\n    grid-template-columns: 1.4fr 1fr 1fr;\n    gap: 2.5rem;\n  }\n}\n\n.footer-brand-title {\n  font-family: var(--font-serif);\n  font-size: 1.75rem;\n  font-weight: 500;\n  display: block;\n  margin-bottom: 0.75rem;\n  color: var(--text-primary);\n}\n\n.footer-brand-desc {\n  font-size: 0.8125rem;\n  line-height: 1.7;\n  color: var(--text-secondary);\n  max-width: 320px;\n  margin-bottom: 1.25rem;\n}\n\n.footer-brand-desk {\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n  font-family: var(--font-mono);\n  font-size: 0.6875rem;\n  color: var(--text-muted);\n}\n\n.desk-indicator-dot {\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  background-color: var(--accent-emerald);\n}\n\n.footer-heading {\n  font-family: var(--font-mono);\n  font-size: 0.6875rem;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.12em;\n  color: var(--text-primary);\n  margin-bottom: 1rem;\n}\n\n.footer-links-list {\n  list-style: none;\n  display: flex;\n  flex-direction: column;\n  gap: 0.65rem;\n}\n\n.footer-links-list a {\n  font-size: 0.8125rem;\n  color: var(--text-secondary);\n}\n\n.footer-links-list a:hover {\n  color: var(--text-primary);\n  padding-left: 0.25rem;\n}\n\n.footer-colophon-text {\n  font-size: 0.8125rem;\n  line-height: 1.65;\n  color: var(--text-secondary);\n  margin-bottom: 1rem;\n}\n\n.footer-typography-spec {\n  font-family: var(--font-mono);\n  font-size: 0.6875rem;\n  color: var(--text-subtle);\n  line-height: 1.5;\n}\n\n.footer-subbar {\n  padding-top: 1.75rem;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  flex-wrap: wrap;\n  gap: 1rem;\n  font-family: var(--font-mono);\n  font-size: 0.6875rem;\n  color: var(--text-subtle);\n}\n\n.footer-subbar-right {\n  display: flex;\n  align-items: center;\n  gap: 1.25rem;\n}\n\n.footer-rss-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.4rem;\n  color: var(--text-muted);\n}\n\n.footer-rss-badge:hover {\n  color: var(--text-primary);\n}\n\n.rss-dot {\n  width: 5px;\n  height: 5px;\n  border-radius: 50%;\n  background-color: #D97706;\n}\n\n.btn-back-to-top {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.35rem;\n  background: none;\n  border: 1px solid var(--border-subtle);\n  border-radius: 4px;\n  padding: 0.25rem 0.6rem;\n  font-family: var(--font-mono);\n  font-size: 0.6875rem;\n  color: var(--text-secondary);\n  cursor: pointer;\n  transition: var(--transition-smooth);\n}\n\n.btn-back-to-top:hover {\n  background-color: var(--bg-subtle);\n  color: var(--text-primary);\n  border-color: var(--border-strong);\n}\n";

export const WP_THEME_FUNCTIONS_PHP = "<?php\n/**\n * Atelier Editorial Theme Functions\n *\n * @package AtelierEditorial\n * @author Waleed Alharbi\n */\n\nif (!defined('ABSPATH')) {\n    exit;\n}\n\nfunction atelier_theme_setup() {\n    // Set global content width\n    global $content_width;\n    if (!isset($content_width)) {\n        $content_width = 760;\n    }\n\n    // Add default title tag support\n    add_theme_support('title-tag');\n\n    // Add featured post thumbnail support\n    add_theme_support('post-thumbnails');\n    set_post_thumbnail_size(1200, 750, true);\n\n    // Add HTML5 markup support\n    add_theme_support('html5', [\n        'search-form',\n        'comment-form',\n        'comment-list',\n        'gallery',\n        'caption',\n        'style',\n        'script',\n    ]);\n\n    // Register primary navigation\n    register_nav_menus([\n        'primary' => __('Primary Navigation', 'atelier-editorial'),\n        'footer'  => __('Footer Navigation', 'atelier-editorial'),\n    ]);\n}\nadd_action('after_setup_theme', 'atelier_theme_setup');\n\n/**\n * Enqueue Google Fonts and theme stylesheet\n */\nfunction atelier_enqueue_scripts() {\n    // Google Fonts: Newsreader, Plus Jakarta Sans, JetBrains Mono\n    wp_enqueue_style(\n        'atelier-google-fonts',\n        'https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500&family=Newsreader:ital,opsz,wght@0,6..72,400;0,6..72,500;1,6..72,400&family=Plus+Jakarta+Sans:wght@400;500;600&display=swap',\n        [],\n        null\n    );\n\n    // Main stylesheet\n    wp_enqueue_style(\n        'atelier-main-style',\n        get_stylesheet_uri(),\n        ['atelier-google-fonts'],\n        '1.0.0'\n    );\n\n    // Threaded comment reply script\n    if (is_singular() && comments_open() && get_option('thread_comments')) {\n        wp_enqueue_script('comment-reply');\n    }\n}\nadd_action('wp_enqueue_scripts', 'atelier_enqueue_scripts');\n\n/**\n * Calculate reading time in minutes for any monograph content\n */\nfunction atelier_calculate_reading_time($content = null) {\n    if (null === $content) {\n        $content = get_post_field('post_content', get_the_ID());\n    }\n    $clean_content = strip_shortcodes($content);\n    $clean_content = wp_strip_all_tags($clean_content);\n    $word_count = str_word_count($clean_content);\n    $minutes = ceil($word_count / 200);\n    return max(1, $minutes);\n}\n\n/**\n * Ensure excerpt has custom clean length\n */\nfunction atelier_excerpt_length($length) {\n    return 26;\n}\nadd_filter('excerpt_length', 'atelier_excerpt_length');\n\nfunction atelier_excerpt_more($more) {\n    return '...';\n}\nadd_filter('excerpt_more', 'atelier_excerpt_more');\n\n/**\n * REST API enhancements for headless usage\n */\nadd_action('rest_api_init', function () {\n    register_rest_field('post', 'reading_time', [\n        'get_callback' => function ($post_arr) {\n            return atelier_calculate_reading_time($post_arr['content']['rendered']);\n        },\n        'schema' => [\n            'description' => 'Estimated reading time in minutes',\n            'type'        => 'integer',\n        ],\n    ]);\n});\n";

