export const WP_THEME_INDEX_PHP = "<?php\n/**\n * Main Index / Ledger Template for Atelier Editorial\n *\n * Conforms strictly to zero categories, tags, or hashtag clutter.\n * Single-author long-form publication architecture.\n *\n * @package AtelierEditorial\n * @author Waleed Alharbi\n */\nget_header();\n\nif (have_posts()) :\n    $post_count = 0;\n    while (have_posts()) : the_post();\n        $post_count++;\n\n        // Render first post on page 1 as the Featured Asymmetric Lead Story\n        if (1 === $post_count && !is_paged()) :\n            ?>\n            <section class=\"hero-lead-section\" aria-label=\"<?php esc_attr_e('Featured Monograph', 'atelier-editorial'); ?>\">\n                <div class=\"hero-lead-grid\">\n                    <!-- Left: Lead Story Prose & Context -->\n                    <div class=\"hero-lead-content\">\n                        <div class=\"hero-lead-kicker\">\n                            <span class=\"kicker-pill\">Lead Story &bull; Featured Release</span>\n                            <span class=\"kicker-date\"><?php echo get_the_date('M j, Y'); ?></span>\n                        </div>\n\n                        <h1 class=\"hero-lead-title\">\n                            <a href=\"<?php the_permalink(); ?>\"><?php the_title(); ?></a>\n                        </h1>\n\n                        <div class=\"hero-lead-excerpt\">\n                            <?php the_excerpt(); ?>\n                        </div>\n\n                        <div class=\"hero-lead-footer\">\n                            <div class=\"hero-author-badge\">\n                                <div class=\"author-avatar-mini\">W</div>\n                                <div class=\"author-meta-text\">\n                                    <span class=\"author-name\">Waleed Alharbi</span>\n                                    <span class=\"author-role\"><?php echo esc_html(atelier_calculate_reading_time()); ?> min read</span>\n                                </div>\n                            </div>\n\n                            <a href=\"<?php the_permalink(); ?>\" class=\"hero-cta-button\">\n                                <span>Read Monograph</span>\n                                <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"></line><polyline points=\"12 5 19 12 12 19\"></polyline></svg>\n                            </a>\n                        </div>\n                    </div>\n\n                    <!-- Right: Lead Story Visual Canvas -->\n                    <div class=\"hero-lead-media\">\n                        <a href=\"<?php the_permalink(); ?>\" class=\"hero-media-anchor\" tabindex=\"-1\" aria-hidden=\"true\">\n                            <?php if (has_post_thumbnail()) : ?>\n                                <?php the_post_thumbnail('large', ['class' => 'hero-media-img']); ?>\n                            <?php else : ?>\n                                <div class=\"hero-media-placeholder\">\n                                    <span class=\"placeholder-kicker\">Atelier Monograph</span>\n                                    <span class=\"placeholder-title\"><?php the_title(); ?></span>\n                                </div>\n                            <?php endif; ?>\n                        </a>\n                    </div>\n                </div>\n            </section>\n\n            <!-- Section Headline: Fresh Editions / Chronological Archive -->\n            <div class=\"ledger-section-header\" id=\"archive\">\n                <div>\n                    <h2 class=\"ledger-section-title\">Chronological Archive</h2>\n                    <p class=\"ledger-section-desc\">Monographs &amp; essays published on contemporary typography, architecture, and slow prose.</p>\n                </div>\n                <div class=\"ledger-count-indicator\">\n                    <span>Archival Catalogue</span>\n                </div>\n            </div>\n\n            <div class=\"monographs-editorial-grid\">\n            <?php\n            continue;\n        endif;\n\n        if (1 === $post_count && is_paged()) :\n            ?>\n            <div class=\"ledger-section-header\" style=\"margin-top: 2rem;\" id=\"archive\">\n                <div>\n                    <h1 class=\"ledger-section-title\">Chronological Archive</h1>\n                    <p class=\"ledger-section-desc\">Folio Volume IV &bull; Page <?php echo esc_html(max(1, get_query_var('paged'))); ?></p>\n                </div>\n            </div>\n            <div class=\"monographs-editorial-grid\">\n            <?php\n        endif;\n        ?>\n\n        <!-- Article Monograph Card -->\n        <article id=\"post-<?php the_ID(); ?>\" <?php post_class('monograph-card'); ?>>\n            <div class=\"card-media-wrapper\">\n                <a href=\"<?php the_permalink(); ?>\" class=\"card-media-link\" aria-label=\"<?php the_title_attribute(); ?>\">\n                    <?php if (has_post_thumbnail()) : ?>\n                        <?php the_post_thumbnail('medium_large', ['class' => 'card-thumbnail-img']); ?>\n                    <?php else : ?>\n                        <div class=\"card-thumbnail-fallback\">\n                            <span>Atelier Folio</span>\n                        </div>\n                    <?php endif; ?>\n                </a>\n            </div>\n\n            <div class=\"card-content-wrapper\">\n                <div class=\"card-unboxed-meta\">\n                    <span class=\"meta-date\"><?php echo get_the_date('M j, Y'); ?></span>\n                    <span class=\"meta-separator\">&bull;</span>\n                    <span class=\"meta-read-time\"><?php echo esc_html(atelier_calculate_reading_time()); ?> min read</span>\n                </div>\n\n                <h3 class=\"card-monograph-title\">\n                    <a href=\"<?php the_permalink(); ?>\"><?php the_title(); ?></a>\n                </h3>\n\n                <div class=\"card-monograph-excerpt\">\n                    <?php the_excerpt(); ?>\n                </div>\n\n                <div class=\"card-monograph-footer\">\n                    <span class=\"card-curator\">Curated by Waleed Alharbi</span>\n                    <a href=\"<?php the_permalink(); ?>\" class=\"card-read-link\">Read Monograph &rarr;</a>\n                </div>\n            </div>\n        </article>\n\n        <?php\n    endwhile;\n\n    echo '</div><!-- .monographs-editorial-grid -->';\n\n    // Curatorial Sections on Front Page\n    if (!is_paged()) :\n        ?>\n        <!-- Curatorial Pull-Quote Break -->\n        <section class=\"curatorial-quote-break\" aria-label=\"<?php esc_attr_e('Curatorial Thesis', 'atelier-editorial'); ?>\">\n            <div class=\"quote-break-inner\">\n                <span class=\"quote-ornament\">&ldquo;</span>\n                <blockquote class=\"quote-break-text\">\n                    The highest virtue of an essay is not velocity, but resonance. Slow reading is the deliberate reclamation of cognitive sovereignty.\n                </blockquote>\n                <cite class=\"quote-break-author\">&mdash; Waleed Alharbi, Editorial Curator</cite>\n            </div>\n        </section>\n\n        <!-- Archival Statistics / Publication Metrics -->\n        <section class=\"archival-metrics-section\" aria-label=\"<?php esc_attr_e('Publication Metrics', 'atelier-editorial'); ?>\">\n            <div class=\"metrics-grid\">\n                <div class=\"metric-card\">\n                    <span class=\"metric-num\">100%</span>\n                    <span class=\"metric-label\">Sole-Author Curated</span>\n                    <span class=\"metric-sub\">Every monograph written by Waleed Alharbi</span>\n                </div>\n                <div class=\"metric-card\">\n                    <span class=\"metric-num\">0</span>\n                    <span class=\"metric-label\">Adverts or Algorithm Trackers</span>\n                    <span class=\"metric-sub\">Pure, distraction-free reading space</span>\n                </div>\n                <div class=\"metric-card\">\n                    <span class=\"metric-num\">65 Chars</span>\n                    <span class=\"metric-label\">Classical Optical Measure</span>\n                    <span class=\"metric-sub\">Typeset strictly for natural eye scanning</span>\n                </div>\n                <div class=\"metric-card\">\n                    <span class=\"metric-num\">Vol. IV</span>\n                    <span class=\"metric-label\">Autumn Archival Series</span>\n                    <span class=\"metric-sub\">Fortnightly dispatches from the desk</span>\n                </div>\n            </div>\n        </section>\n\n        <!-- Editorial Pillars Section -->\n        <section class=\"editorial-pillars-section\" id=\"pillars\" aria-label=\"<?php esc_attr_e('Editorial Pillars', 'atelier-editorial'); ?>\">\n            <div class=\"pillars-header\">\n                <span class=\"pillars-kicker\">CURATORIAL ARCHITECTURE</span>\n                <h3 class=\"pillars-title\">The Four Pillars of the Atelier</h3>\n                <p class=\"pillars-desc\">A deliberate departure from high-velocity digital clutter in favor of permanence, depth, and typographical composure.</p>\n            </div>\n\n            <div class=\"pillars-grid\">\n                <div class=\"pillar-box\">\n                    <div class=\"pillar-number\">01</div>\n                    <h4 class=\"pillar-box-title\">Monograph Architecture</h4>\n                    <p class=\"pillar-box-body\">Long-form treatises exceeding 2,000 words designed for sustained, uninterrupted focus without cognitive fragmentation.</p>\n                </div>\n                <div class=\"pillar-box\">\n                    <div class=\"pillar-number\">02</div>\n                    <h4 class=\"pillar-box-title\">Classical Typography</h4>\n                    <p class=\"pillar-box-body\">Carefully calibrated Newsreader serifs, JetBrains Mono metadata, proportional spacing, and the 65-character optical measure.</p>\n                </div>\n                <div class=\"pillar-box\">\n                    <div class=\"pillar-number\">03</div>\n                    <h4 class=\"pillar-box-title\">Humane Ergonomics</h4>\n                    <p class=\"pillar-box-body\">Zero advertising banners, zero popups, zero tracking scripts, and absolute elimination of category, tag, or hashtag noise.</p>\n                </div>\n                <div class=\"pillar-box\">\n                    <div class=\"pillar-number\">04</div>\n                    <h4 class=\"pillar-box-title\">Unhurried Velocity</h4>\n                    <p class=\"pillar-box-body\">A fortnightly publication cadence that allows concepts, arguments, and aesthetic treatises to mature prior to release.</p>\n                </div>\n            </div>\n        </section>\n\n        <!-- Postal Dispatch / Subscription Box -->\n        <section class=\"postal-dispatch-section\" aria-label=\"<?php esc_attr_e('Postal Dispatch Subscription', 'atelier-editorial'); ?>\">\n            <div class=\"postal-box-container\">\n                <div class=\"postal-box-text\">\n                    <span class=\"postal-kicker\">MONOGRAPH POSTAL DISPATCH</span>\n                    <h3 class=\"postal-heading\">Subscribe to the Fortnightly Monograph Ledger</h3>\n                    <p class=\"postal-sub\">New long-form essays delivered quietly to your reader without promotional spam, tracking, or sponsored content.</p>\n                </div>\n                <div class=\"postal-box-form\">\n                    <form class=\"postal-subscribe-form\" action=\"<?php echo esc_url(home_url('/')); ?>\" method=\"get\" onsubmit=\"event.preventDefault(); alert('Subscribed to the Atelier Monograph Dispatch.');\">\n                        <input type=\"email\" placeholder=\"colleague@atelier.org\" class=\"postal-email-input\" required />\n                        <button type=\"submit\" class=\"postal-submit-btn\">Receive Dispatches</button>\n                    </form>\n                    <span class=\"postal-guarantee\">&bull; Strictly zero advertising &bull; Unsubscribe at any time</span>\n                </div>\n            </div>\n        </section>\n        <?php\n    endif;\n\n    // Numerical Pagination\n    the_posts_pagination([\n        'mid_size'           => 2,\n        'prev_text'          => __('&larr; Earlier Monographs', 'atelier-editorial'),\n        'next_text'          => __('Subsequent Monographs &rarr;', 'atelier-editorial'),\n        'before_page_number' => '<span class=\"screen-reader-text\">' . __('Page', 'atelier-editorial') . ' </span>',\n    ]);\n\nelse :\n    ?>\n    <div class=\"empty-ledger-view\">\n        <h2 class=\"empty-title\"><?php esc_html_e('No Monographs Registered Yet', 'atelier-editorial'); ?></h2>\n        <p class=\"empty-desc\"><?php esc_html_e('The publication ledger is being prepared. Check back shortly for new editions.', 'atelier-editorial'); ?></p>\n        <a href=\"<?php echo esc_url(home_url('/')); ?>\" class=\"empty-home-link\">&larr; Return to Front Ledger</a>\n    </div>\n    <?php\nendif;\n\nget_footer();\n";

export const WP_THEME_SINGLE_PHP = "<?php\n/**\n * Single Monograph Reader Template for Atelier Editorial\n *\n * Dedicated to deep, distraction-free reading with 65-character optical measures,\n * classical drop caps, unboxed metadata, and zero category clutter.\n *\n * @package AtelierEditorial\n * @author Waleed Alharbi\n */\nget_header();\n\nwhile (have_posts()) : the_post();\n    ?>\n    <article id=\"post-<?php the_ID(); ?>\" <?php post_class('reader-monograph-article'); ?>>\n        \n        <!-- Reader Navigation & Status Bar -->\n        <nav class=\"reader-top-bar\" aria-label=\"<?php esc_attr_e('Monograph Navigation', 'atelier-editorial'); ?>\">\n            <a href=\"<?php echo esc_url(home_url('/')); ?>\" class=\"reader-back-link\">\n                <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"19\" y1=\"12\" x2=\"5\" y2=\"12\"></line><polyline points=\"12 19 5 12 12 5\"></polyline></svg>\n                <span>Back to Archival Ledger</span>\n            </a>\n\n            <div class=\"reader-folio-indicator\">\n                <span class=\"folio-dot\"></span>\n                <span>Monograph #<?php the_ID(); ?> &bull; Sole Edition</span>\n            </div>\n        </nav>\n\n        <!-- Monograph Header -->\n        <header class=\"reader-monograph-header\">\n            <div class=\"reader-unboxed-meta\">\n                <span class=\"meta-date\">Published on <?php echo get_the_date('F j, Y'); ?></span>\n                <span class=\"meta-dot\">&bull;</span>\n                <span class=\"meta-read-time\"><?php echo esc_html(atelier_calculate_reading_time()); ?> min read</span>\n                <span class=\"meta-dot\">&bull;</span>\n                <span class=\"meta-author\">Sole Author &amp; Curator</span>\n            </div>\n\n            <h1 class=\"reader-monograph-title\"><?php the_title(); ?></h1>\n\n            <?php if (has_excerpt()) : ?>\n                <p class=\"reader-monograph-subtitle\"><?php echo get_the_excerpt(); ?></p>\n            <?php endif; ?>\n\n            <div class=\"reader-byline-strip\">\n                <div class=\"byline-avatar\">W</div>\n                <div class=\"byline-details\">\n                    <span class=\"byline-name\">Waleed Alharbi</span>\n                    <span class=\"byline-desc\">Curated Monograph &bull; Copenhagen &amp; Zurich</span>\n                </div>\n            </div>\n        </header>\n\n        <!-- Featured Media Container -->\n        <?php if (has_post_thumbnail()) : ?>\n            <figure class=\"reader-featured-figure\">\n                <?php the_post_thumbnail('full', ['class' => 'reader-featured-img']); ?>\n                <?php if ($caption = get_the_post_thumbnail_caption()) : ?>\n                    <figcaption class=\"reader-featured-caption\"><?php echo esc_html($caption); ?></figcaption>\n                <?php endif; ?>\n            </figure>\n        <?php endif; ?>\n\n        <!-- Monograph Body Prose (Constrained to 65-char optimal measure) -->\n        <div class=\"reader-prose-container editorial-drop-cap\">\n            <?php\n            the_content();\n\n            wp_link_pages([\n                'before'      => '<nav class=\"reader-page-pagination\" aria-label=\"' . esc_attr__('Monograph Pages', 'atelier-editorial') . '\"><span class=\"page-links-title\">' . esc_html__('Monograph Folios:', 'atelier-editorial') . '</span>',\n                'after'       => '</nav>',\n                'link_before' => '<span class=\"page-number\">',\n                'link_after'  => '</span>',\n            ]);\n            ?>\n        </div>\n\n        <!-- Colophon & Author Attribution Card -->\n        <section class=\"reader-author-card\">\n            <div class=\"author-card-inner\">\n                <div class=\"author-portrait-wrap\">\n                    <div class=\"author-portrait-placeholder\">W</div>\n                </div>\n                <div class=\"author-card-content\">\n                    <span class=\"author-card-role\">SOLE AUTHOR &bull; ARCHIVAL CURATOR</span>\n                    <h3 class=\"author-card-name\">Waleed Alharbi</h3>\n                    <p class=\"author-card-bio\">\n                        Architectural essayist, digital typographer, and curator of Atelier. Writing slowly on cognitive restraint, humane software ergonomics, and classical editorial craft free from algorithmic velocity.\n                    </p>\n                    <div class=\"author-card-actions\">\n                        <a href=\"<?php echo esc_url(home_url('/about')); ?>\" class=\"author-card-link\">About Publication &rarr;</a>\n                        <a href=\"<?php echo esc_url(home_url('/contact')); ?>\" class=\"author-card-link\">Send Letter to Desk &rarr;</a>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <!-- Previous / Next Monograph Navigation -->\n        <nav class=\"reader-post-navigation\" aria-label=\"<?php esc_attr_e('Adjacent Monographs', 'atelier-editorial'); ?>\">\n            <div class=\"nav-adjacent-grid\">\n                <div class=\"nav-adjacent-cell nav-prev\">\n                    <?php\n                    $prev_post = get_previous_post();\n                    if ($prev_post) :\n                        ?>\n                        <span class=\"nav-cell-label\">&larr; Previous Monograph</span>\n                        <a href=\"<?php echo esc_url(get_permalink($prev_post->ID)); ?>\" class=\"nav-cell-title\">\n                            <?php echo esc_html(get_the_title($prev_post->ID)); ?>\n                        </a>\n                        <?php\n                    endif;\n                    ?>\n                </div>\n\n                <div class=\"nav-adjacent-cell nav-next\">\n                    <?php\n                    $next_post = get_next_post();\n                    if ($next_post) :\n                        ?>\n                        <span class=\"nav-cell-label\">Next Monograph &rarr;</span>\n                        <a href=\"<?php echo esc_url(get_permalink($next_post->ID)); ?>\" class=\"nav-cell-title\">\n                            <?php echo esc_html(get_the_title($next_post->ID)); ?>\n                        </a>\n                        <?php\n                    endif;\n                    ?>\n                </div>\n            </div>\n        </nav>\n\n        <!-- Comments / Discussions -->\n        <?php\n        if (comments_open() || get_comments_number()) :\n            ?>\n            <div class=\"reader-comments-section\">\n                <?php comments_template(); ?>\n            </div>\n            <?php\n        endif;\n        ?>\n\n    </article>\n    <?php\nendwhile;\n\nget_footer();\n";

export const WP_THEME_PAGE_PHP = "<?php\n/**\n * Standalone Page Template for Atelier Editorial\n *\n * Designed for About, Manifesto, Colophon, and Correspondence pages.\n *\n * @package AtelierEditorial\n * @author Waleed Alharbi\n */\nget_header();\n\nwhile (have_posts()) : the_post();\n    ?>\n    <article id=\"page-<?php the_ID(); ?>\" <?php post_class('editorial-page-wrapper'); ?>>\n        <header class=\"editorial-page-header\">\n            <span class=\"editorial-page-kicker\">ATELIER FOLIO &bull; ARCHIVAL PAGE</span>\n            <h1 class=\"editorial-page-title\"><?php the_title(); ?></h1>\n            <?php if (has_excerpt()) : ?>\n                <p class=\"editorial-page-subtitle\"><?php echo get_the_excerpt(); ?></p>\n            <?php endif; ?>\n        </header>\n\n        <?php if (has_post_thumbnail()) : ?>\n            <div class=\"editorial-page-media\">\n                <?php the_post_thumbnail('full'); ?>\n            </div>\n        <?php endif; ?>\n\n        <div class=\"editorial-page-content editorial-drop-cap\">\n            <?php\n            the_content();\n\n            wp_link_pages([\n                'before' => '<div class=\"page-links\">' . esc_html__('Pages:', 'atelier-editorial'),\n                'after'  => '</div>',\n            ]);\n            ?>\n        </div>\n    </article>\n    <?php\nendwhile;\n\nget_footer();\n";

export const WP_THEME_ARCHIVE_PHP = "<?php\n/**\n * Archive Template for Atelier Editorial\n *\n * Conforms strictly to zero categories and tag taxonomy omissions.\n * Displays date, author, and chronological ledger collections.\n *\n * @package AtelierEditorial\n * @author Waleed Alharbi\n */\nget_header();\n?>\n\n<header class=\"archive-ledger-header\">\n    <div class=\"archive-kicker\">CHRONOLOGICAL ARCHIVE</div>\n    <h1 class=\"archive-title\">\n        <?php\n        if (is_date()) {\n            the_archive_title();\n        } else {\n            echo esc_html__('Historical Monograph Ledger', 'atelier-editorial');\n        }\n        ?>\n    </h1>\n    <p class=\"archive-desc\">\n        Complete chronological index of essays, reflections, and dispatches published by Waleed Alharbi.\n    </p>\n</header>\n\n<?php if (have_posts()) : ?>\n    <div class=\"monographs-editorial-grid\">\n        <?php\n        while (have_posts()) : the_post();\n            ?>\n            <article id=\"post-<?php the_ID(); ?>\" <?php post_class('monograph-card'); ?>>\n                <div class=\"card-media-wrapper\">\n                    <a href=\"<?php the_permalink(); ?>\" class=\"card-media-link\" aria-label=\"<?php the_title_attribute(); ?>\">\n                        <?php if (has_post_thumbnail()) : ?>\n                            <?php the_post_thumbnail('medium_large', ['class' => 'card-thumbnail-img']); ?>\n                        <?php else : ?>\n                            <div class=\"card-thumbnail-fallback\">\n                                <span>Atelier Folio</span>\n                            </div>\n                        <?php endif; ?>\n                    </a>\n                </div>\n\n                <div class=\"card-content-wrapper\">\n                    <div class=\"card-unboxed-meta\">\n                        <span class=\"meta-date\"><?php echo get_the_date('M j, Y'); ?></span>\n                        <span class=\"meta-separator\">&bull;</span>\n                        <span class=\"meta-read-time\"><?php echo esc_html(atelier_calculate_reading_time()); ?> min read</span>\n                    </div>\n\n                    <h3 class=\"card-monograph-title\">\n                        <a href=\"<?php the_permalink(); ?>\"><?php the_title(); ?></a>\n                    </h3>\n\n                    <div class=\"card-monograph-excerpt\">\n                        <?php the_excerpt(); ?>\n                    </div>\n\n                    <div class=\"card-monograph-footer\">\n                        <span class=\"card-curator\">Curated by Waleed Alharbi</span>\n                        <a href=\"<?php the_permalink(); ?>\" class=\"card-read-link\">Read &rarr;</a>\n                    </div>\n                </div>\n            </article>\n            <?php\n        endwhile;\n        ?>\n    </div>\n\n    <?php\n    the_posts_pagination([\n        'mid_size'  => 2,\n        'prev_text' => __('&larr; Earlier Monographs', 'atelier-editorial'),\n        'next_text' => __('Subsequent Monographs &rarr;', 'atelier-editorial'),\n    ]);\nelse :\n    ?>\n    <div class=\"empty-ledger-view\">\n        <h2 class=\"empty-title\"><?php esc_html_e('No Monographs Found', 'atelier-editorial'); ?></h2>\n        <p class=\"empty-desc\"><?php esc_html_e('No records found in this chronological ledger period.', 'atelier-editorial'); ?></p>\n        <a href=\"<?php echo esc_url(home_url('/')); ?>\" class=\"empty-home-link\">&larr; Return to Front Ledger</a>\n    </div>\n<?php\nendif;\n\nget_footer();\n";

export const WP_THEME_SEARCH_PHP = "<?php\n/**\n * Search Results Template for Atelier Editorial\n *\n * @package AtelierEditorial\n * @author Waleed Alharbi\n */\nget_header();\n?>\n\n<header class=\"archive-ledger-header\">\n    <div class=\"archive-kicker\">SEARCH LEDGER RESULTS</div>\n    <h1 class=\"archive-title\">\n        <?php\n        /* translators: %s: search query */\n        printf(esc_html__('Query: &ldquo;%s&rdquo;', 'atelier-editorial'), '<span>' . get_search_query() . '</span>');\n        ?>\n    </h1>\n    <p class=\"archive-desc\">\n        <?php\n        global $wp_query;\n        $total_results = $wp_query->found_posts;\n        printf(\n            esc_html(_n('%d archival monograph located', '%d archival monographs located', $total_results, 'atelier-editorial')),\n            $total_results\n        );\n        ?>\n    </p>\n\n    <!-- Search Form Input -->\n    <div class=\"search-page-form-wrap\">\n        <?php get_search_form(); ?>\n    </div>\n</header>\n\n<?php if (have_posts()) : ?>\n    <div class=\"monographs-editorial-grid\">\n        <?php\n        while (have_posts()) : the_post();\n            ?>\n            <article id=\"post-<?php the_ID(); ?>\" <?php post_class('monograph-card'); ?>>\n                <div class=\"card-media-wrapper\">\n                    <a href=\"<?php the_permalink(); ?>\" class=\"card-media-link\" aria-label=\"<?php the_title_attribute(); ?>\">\n                        <?php if (has_post_thumbnail()) : ?>\n                            <?php the_post_thumbnail('medium_large', ['class' => 'card-thumbnail-img']); ?>\n                        <?php else : ?>\n                            <div class=\"card-thumbnail-fallback\">\n                                <span>Atelier Folio</span>\n                            </div>\n                        <?php endif; ?>\n                    </a>\n                </div>\n\n                <div class=\"card-content-wrapper\">\n                    <div class=\"card-unboxed-meta\">\n                        <span class=\"meta-date\"><?php echo get_the_date('M j, Y'); ?></span>\n                        <span class=\"meta-separator\">&bull;</span>\n                        <span class=\"meta-read-time\"><?php echo esc_html(atelier_calculate_reading_time()); ?> min read</span>\n                    </div>\n\n                    <h3 class=\"card-monograph-title\">\n                        <a href=\"<?php the_permalink(); ?>\"><?php the_title(); ?></a>\n                    </h3>\n\n                    <div class=\"card-monograph-excerpt\">\n                        <?php the_excerpt(); ?>\n                    </div>\n\n                    <div class=\"card-monograph-footer\">\n                        <span class=\"card-curator\">Curated by Waleed Alharbi</span>\n                        <a href=\"<?php the_permalink(); ?>\" class=\"card-read-link\">Read &rarr;</a>\n                    </div>\n                </div>\n            </article>\n            <?php\n        endwhile;\n        ?>\n    </div>\n\n    <?php\n    the_posts_pagination([\n        'mid_size'  => 2,\n        'prev_text' => __('&larr; Earlier Results', 'atelier-editorial'),\n        'next_text' => __('More Results &rarr;', 'atelier-editorial'),\n    ]);\nelse :\n    ?>\n    <div class=\"empty-ledger-view\">\n        <h2 class=\"empty-title\"><?php esc_html_e('No Matches Found in the Monograph Ledger', 'atelier-editorial'); ?></h2>\n        <p class=\"empty-desc\"><?php esc_html_e('No published monographs correspond with this search query. Try broader keywords or return to the main ledger.', 'atelier-editorial'); ?></p>\n        <a href=\"<?php echo esc_url(home_url('/')); ?>\" class=\"empty-home-link\">&larr; Return to Front Ledger</a>\n    </div>\n<?php\nendif;\n\nget_footer();\n";

